ALTER TABLE "l_CustomerSalesOrders" ADD CONSTRAINT "fk_l_CustomerSalesOrders_1" FOREIGN KEY ("r_CustomerSalesOrders_target_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductInventory" ADD CONSTRAINT "fk_l_ProductInventory_0" FOREIGN KEY ("r_ProductInventory_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductInventory" ADD CONSTRAINT "fk_l_ProductInventory_1" FOREIGN KEY ("r_ProductInventory_target_id") REFERENCES "c_InventoryItem" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_0" FOREIGN KEY ("r_PurchaseOrderProducts_source_id") REFERENCES "c_PurchaseOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_1" FOREIGN KEY ("r_PurchaseOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderInvoices" ADD CONSTRAINT "fk_l_SalesOrderInvoices_0" FOREIGN KEY ("r_SalesOrderInvoices_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderInvoices" ADD CONSTRAINT "fk_l_SalesOrderInvoices_1" FOREIGN KEY ("r_SalesOrderInvoices_target_id") REFERENCES "c_Invoice" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_0" FOREIGN KEY ("r_SalesOrderProducts_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_1" FOREIGN KEY ("r_SalesOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_VendorPurchaseOrders" ADD CONSTRAINT "fk_l_VendorPurchaseOrders_0" FOREIGN KEY ("r_VendorPurchaseOrders_source_id") REFERENCES "c_Vendor" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_VendorPurchaseOrders" ADD CONSTRAINT "fk_l_VendorPurchaseOrders_1" FOREIGN KEY ("r_VendorPurchaseOrders_target_id") REFERENCES "c_PurchaseOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_CustomerSalesOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_SalesOrder" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CustomerSalesOrders" l WHERE l."r_CustomerSalesOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CustomerSalesOrders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CustomerSalesOrders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_SalesOrder" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerSalesOrders"();
CREATE CONSTRAINT TRIGGER "ct_CustomerSalesOrders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CustomerSalesOrders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerSalesOrders"();
CREATE FUNCTION "require_ProductInventory"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_InventoryItem" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ProductInventory" l WHERE l."r_ProductInventory_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ProductInventory'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ProductInventory_target" AFTER INSERT OR UPDATE OR DELETE ON "c_InventoryItem" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductInventory"();
CREATE CONSTRAINT TRIGGER "ct_ProductInventory_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ProductInventory" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductInventory"();
CREATE FUNCTION "require_SalesOrderInvoices"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Invoice" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_SalesOrderInvoices" l WHERE l."r_SalesOrderInvoices_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: SalesOrderInvoices'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_SalesOrderInvoices_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Invoice" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SalesOrderInvoices"();
