CREATE FUNCTION "require_VendorPurchaseOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_PurchaseOrder" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_VendorPurchaseOrders" l WHERE l."r_VendorPurchaseOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: VendorPurchaseOrders'; END IF; RETURN NULL; END; $ymap$;
